const { filter, sorts, pageSize, startCursor } = $.input;
const body = { page_size: Math.min(pageSize || 25, 100) };
if (filter) body.filter = filter;
if (sorts && sorts.length > 0) body.sorts = sorts;
if (startCursor) body.start_cursor = startCursor;
return body;

const resp = $.steps.queryDatabase.response || {};
const results = resp.results || [];

function extractTitle(props) {
  for (const key of Object.keys(props)) {
    const prop = props[key];
    if (prop.type === 'title' && prop.title && prop.title.length > 0) {
      return prop.title.map(t => t.plain_text || '').join('');
    }
  }
  return '';
}

return {
  pages: results.map(p => ({
    id: p.id,
    title: extractTitle(p.properties || {}),
    url: p.url || '',
    properties: p.properties || {},
    createdTime: p.created_time,
    lastEditedTime: p.last_edited_time
  })),
  count: results.length,
  hasMore: resp.has_more || false,
  nextCursor: resp.next_cursor || null,
  summary: `Retrieved ${results.length} page${results.length === 1 ? '' : 's'} from database`
};
